module top_module(
  input clk, // clock signal
  input signed [15:0] ain, // analog input signal
  output reg dout, // 1-bit digital output signal
  output reg signed [15:0] aout // analog output signal
);parameter N = 32; // oversampling rate

reg signed [15:0] delta; // delta value
reg signed [15:0] integrator; // integrator value
reg signed [15:0] quant_error; // quantization error
reg signed [15:0] filter_out; // filter output

// noise shaper coefficients
parameter [1:0] b0 = 2'b11;
parameter [1:0] b1 = 2'b00;
parameter [1:0] a1 = 2'b10;

// digital filter coefficients
parameter [15:0] b0f = 16'h7FFF;
parameter [15:0] b1f = 16'h8000;
parameter [15:0] a1f = 16'h0000;

// sigma-delta modulator
always @(posedge clk) begin
  delta <= ain - integrator; // calculate delta value
  quant_error <= delta + (quant_error >> 1); // add quantization error
  integrator <= integrator + (quant_error * b0) - (dout * b1); // update integrator
  dout <= (integrator > 0); // output 1-bit digital signal
end

// sigma-delta demodulator
always @(posedge clk) begin
  filter_out <= (dout * b0f) + (filter_out * b1f) - (a1f * aout); // calculate filter output
  aout <= filter_out >> 16; // output analog signal
end

endmodule

