module fsm (
  input in,
  input [2:0] state,
  output reg [2:0] next_state,
  output reg out);parameter L=0, M=1, N=2, O=3, P=4;

    always_comb begin
        case (state)
            L: next_state = in ? N : M;
            M: next_state = in ? O : L;
            N: next_state = in ? M : P;
            O: next_state = in ? L : N;
            P: next_state = in ? N : O;
        endcase
    end

    assign out = (state==M) || (state==O);

endmodule

