module top_module(
    input clk,
    output reg out
    );integer count = 0;

    always @(posedge clk) begin
	   count = count + 1;
		if(count == 6250000) begin
		  count = 0;
		  out = 1'b1;
		end
		else begin
			out = 1'b0;
		end
    end

endmodule

