module top_module(
    input D,
    input CLK,
    input DE,
    output Q,
    output Q_N
);// Local signals
    wire buf_Q;
    wire mux_out;

    // 2-to-1 multiplexer behavior using standard gates
    assign mux_out = DE ? D : buf_Q; // Multiplexer: if DE is high, output D, else output buf_Q

    // D flip-flop with behavior
    reg buf_Q_int; // Internal register for D flip-flop output

    always @(posedge CLK) begin
        buf_Q_int <= mux_out; // Trigger on rising clock edge
    end

    assign buf_Q = buf_Q_int; // Connect internal register to buf_Q

    // Buffer with no delay
    assign Q = buf_Q; // Direct assignment for output Q

    // Inverter with no delay
    assign Q_N = ~buf_Q; // Inverting buf_Q for output Q_N

endmodule

