module top_module(
    input clk,
    input rst,
    input en,
    input [1:0] sel,
    output reg [3:0] out
);reg [3:0] count_reg;
reg [3:0] count_next;

always @ (posedge clk) begin
    if (rst) begin
        count_reg <= 4'b0;
    end
    else if (en) begin
        count_reg <= count_next;
    end
end

always @ (*) begin
    case (sel)
        2'b00: count_next = count_reg[0];
        2'b01: count_next = count_reg[1];
        2'b10: count_next = count_reg[2];
        2'b11: count_next = count_reg[3];
    endcase
end

assign out = count_reg[sel];

endmodule

