description:
Design a sequential circuit that operates under the control of a clock signal and a reset signal, implementing a register-like functionality for three outputs (a, b, and c). On a low reset signal (reset_l), the outputs a and b are reset to 0, while c is set to 1. When the reset signal is high, the circuit samples the inputs (in_a, in_b, in_c) at the positive edge of the clock and updates the outputs accordingly. The additional logic blocks ensure that the outputs maintain their values under specific conditions, reflecting an input-driven state machine design with asynchronous reset capabilities.
module top_module(/*AUTOARG*/
          // Outputs
          a, b, c,
          // Inputs
          clk, reset_l, in_a, in_b, in_c
          );

code:
module top_module(/*AUTOARG*/
          // Outputs
          a, b, c,
          // Inputs
          clk, reset_l, in_a, in_b, in_c
          );input  clk, reset_l, in_a,in_b,in_c;
   output a,b,c;
   reg    a,b,c;

   // Reset behavior for always block 1
   always @(posedge clk or negedge reset_l) begin
      if (!reset_l) begin
         c <= 1;
         /*AUTORESET*/
         // Beginning of autoreset for uninitialized flops
         a <= #1 0;
         b <= #1 0;
         // End of automatics
      end
      else begin
         a <= in_a;
         b <= in_b;
         c <= in_c;
      end
   end

   // Reset behavior for always block 2
   always @(posedge clk or negedge reset_l) begin
      casex ({reset_l,in_a})
        2'b1_x: begin
           a <= in_a;
           b <= in_b;
           c <= in_c;
        end
        2'b0_x: begin
           c <= 1;
           /*AUTORESET*/
           // Beginning of autoreset for uninitialized flops
           a <= #1 0;
           b <= #1 0;
           // End of automatics
        end
      endcase
   end

   // Reset behavior for always block 3
   always @(/*AS*/in_a or in_b or reset_l) begin
      casex ({reset_l,in_a})
        2'b1_x: begin
           a = in_a;
           b = in_b;
        end
        2'b0_x: begin
           c = 1;
           /*AUTORESET*/
           // Beginning of autoreset for uninitialized flops
           a = 0;
           b = 0;
           // End of automatics
        end
      endcase
   end

endmodule

