   );

code:
module top_module(
   output reg validData,
   input ctrl_clk,
   inout wire ctrl_data // Declare ctrl_data as wire
   );reg ctrl_data_reg; // Create a register to hold the data

   always @(posedge ctrl_clk) begin
      ctrl_data_reg <= ~ctrl_data_reg; // Toggle the register
      validData <= ~validData;
   end

   // Assign the internal register to the inout wire
   assign ctrl_data = ctrl_data_reg;

endmodule

