module top_module(
    input [4:0] i,
    output [4:0] o0,
    output [4:0] o1,
    output [4:0] o2,
    output [4:0] o3,
    output [4:0] o4
);assign o0 = {i[3:0], 1'b0};
    assign o1 = {1'b0, i[4:1]};
    assign o2 = i & 5'b10101;
    assign o3 = i | 5'b01010;
    assign o4 = i ^ 5'b11100;

endmodule

module top_module(
  clk,
  rst,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  data_count
);input clk;
input rst;
input [31 : 0] din;
input wr_en;
input rd_en;
output [31 : 0] dout;
output full;
output empty;
output [12 : 0] data_count;

wire [31:0] dout_int;
wire full_int;
wire empty_int;
wire [12:0] data_count_int;

// Define FIFO parameters replacing with a valid FIFO implementation or instantiate correctly
parameter DATA_WIDTH = 32;
parameter DEPTH = 4096;

reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];
reg [12:0] head, tail;
reg [12:0] count;

assign empty = (count == 0);
assign full = (count == DEPTH);
assign dout = (empty) ? 32'b0 : memory[head];

assign data_count = count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        head <= 0;
        tail <= 0;
        count <= 0;
    end else begin
        if (wr_en && !full) begin
            memory[tail] <= din;
            tail <= (tail + 1) % DEPTH;
            count <= count + 1;
        end
        if (rd_en && !empty) begin
            head <= (head + 1) % DEPTH;
            count <= count - 1;
        end
    end
end

endmodule

module top_module(
    input a, b,
    output xor_out, cout, sum);// Structural implementation of XOR gate using MUX
    wire mux_out;
    assign mux_out = (a ^ b) ? 1'b1 : 1'b0;
    assign xor_out = mux_out;

    // Half adder implementation using XOR and AND gates
    wire ha_xor_out, ha_and_out;
    assign ha_xor_out = a ^ b;
    assign ha_and_out = a & b;
    assign cout = ha_and_out;
    assign sum = ha_xor_out;

endmodule

