description:
Design a watchdog timer circuit that generates a timeout signal based on clock input. The timer counts down from a specified initial value (one second) and outputs a watchdog (wd) signal that is set to high when the timer reaches zero. Upon asserting a reset signal, the timer resets to its initial value. Additionally, if the wd signal is high and the counter reaches a predetermined timeout value (two seconds), it resets the timer to the initial state and activates the reset condition. This circuit is crucial for monitoring system activity, ensuring that a reset is triggered if a fault or unresponsiveness is detected.
module top_module(
  input clk,
  input reset,
  output reg wd
);

code:
module top_module(
  input clk,
  input reset,
  output reg wd
);parameter initial_value = 100000000; // initial value of the watchdog timer (e.g., 1 second)
parameter timeout_value = 200000000; // timeout value (e.g., 2 seconds)

reg [31:0] counter;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    counter <= initial_value;
    wd <= 1'b0;
  end else if (counter == 0) begin
    counter <= initial_value;
    wd <= 1'b1;
  end else begin
    counter <= counter - 1;
    wd <= 1'b0;
  end
end

always @(posedge clk) begin
  if (wd) begin
    if (counter == timeout_value) begin
      counter <= initial_value;
      wd <= 1'b0;
      // reset is not changed here
    end else begin
      counter <= counter + 1;
    end
  end else if (reset) begin
    counter <= initial_value;
  end
end

endmodule

