module top_module (
    input clk,
    input areset,
    input [7:0] d,
    input load,
    output [7:0] q );reg [7:0] q_reg;

    always @(posedge clk or posedge areset) begin
        if (areset)
            q_reg <= 8'b00000000;
        else if (load)
            q_reg <= d;
        else
            q_reg <= {q_reg[6:0], 1'b0};
    end

    assign q = q_reg;

endmodule

