module fsm (
	input clk,
	input reset_n,
	input a,
	input b,
	output reg m);

	parameter X=0, Y=1, S1=2, S2=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (!reset_n) state <= X;
		else state <= next;
	end

	always_comb begin
		case (state)
			X: next = a ? Y : X;
			Y: next = b ? S1 : S2;
			S1: next = b ? S2 : X;
			S2: next = a ? Y : X;
			default: next = 'x;
		endcase
	end

	assign m = (state == S1);

endmodule

