description:
Design a module that functions as a combined priority and binary encoder for 4 input signals, producing 2 output signals. The circuit first checks for any active input; if at least one input is high, it employs a binary encoding method to convey the higher-order bits of the active input. If no input is active, it defaults to a priority encoding method, which outputs a specific binary representation based on the highest active input. This design effectively allows for the digitization of multiple input signals into a more manageable binary format, enhancing the interpretation of active signals in a system.
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);

code:
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);parameter n = 4; // number of input signals
parameter m = 2; // number of output signals

// Priority Encoder
function [m-1:0] priority_encoder;
  input [n-1:0] in;
  begin
    casez(in)
      4'b1000: priority_encoder = 2'b00;
      4'b0100: priority_encoder = 2'b01;
      4'b0010: priority_encoder = 2'b10;
      4'b0001: priority_encoder = 2'b11;
      default: priority_encoder = 2'b00;
    endcase
  end
endfunction

// Binary Encoder
function [m-1:0] binary_encoder;
  input [n-1:0] in;
  begin
    if (in == 0) begin
      binary_encoder = 2'b00;
    end else begin
      binary_encoder = {in[3], in[2]};
    end
  end
endfunction

// Connect inputs to encoders and generate output signals
assign out = (in != 0) ? binary_encoder(in) : priority_encoder(in);

endmodule

module top_module(A, B, Ci, S, Co);input A, B, Ci;
  output S, Co;
  wire n9, n10, n11;

  // Logic for Full Adder
  assign n9 = A & B;              // AND gate for A and B
  assign n11 = A ^ B;             // XOR gate for A and B
  assign S = n11 ^ Ci;            // XOR gate for sum output
  assign n10 = (A & B) | (n11 & Ci); // OR gate for carry output
  assign Co = n10;                // Carry output

endmodule

description:
Design a LED flasher module that generates a blinking output based on a clock signal and a control input. This circuit uses a finite state machine to manage three states: reset, off, and on. When the `LED_flash` input is asserted, the LED output toggles between high and low states at specified intervals (HIGH_PERIOD and LOW_PERIOD), determined by a counter. If `LED_flash` is deasserted, the circuit returns to the reset state, effectively stopping the flashing behavior.
module top_module(
  input clk,
  input LED_flash,
  output reg LED_out
);

code:
module top_module(
  input clk,
  input LED_flash,
  output reg LED_out
);// Parameters
  parameter HIGH_PERIOD = 600;
  parameter LOW_PERIOD = 600;
  parameter s_reset = 2'd0;
  parameter s_off = 2'd1;
  parameter s_on = 2'd2;

  // Signals & Registers
  reg [15:0] cnt = 0;
  reg [1:0] state = s_reset;

  // State Machine
  always @(posedge clk) begin
    case (state)
      s_reset:
        begin
          cnt <= 0;
          if (LED_flash)
            state <= s_on;
        end

      s_off:
        begin
          cnt <= cnt + 1;
          LED_out <= 0;
          if (cnt == LOW_PERIOD && LED_flash)
            state <= s_on;
          else if (!LED_flash)
            state <= s_reset;
        end

      s_on:
        begin
          cnt <= cnt + 1;
          LED_out <= 1;
          if (cnt == HIGH_PERIOD && LED_flash)
            state <= s_off;
          else if (!LED_flash)
            state <= s_reset;
        end
    endcase
  end

endmodule

module up_down_counter_4bit (counter_out, clk, reset, en, up_down);
   input clk, reset, en, up_down;
   output [3:0] counter_out;

   reg [3:0] counter_out;

   always @(posedge clk or posedge reset) begin
      if (reset)
         counter_out <= 4'b0;
      else if (en) begin
         if (up_down)
            counter_out <= counter_out + 1;
         else
            counter_out <= counter_out - 1;
      end
   end

endmodule

