module top_module(
    input clk10hz,
    input pb,
    output reg isKP
);reg [4:0] count;

always @(posedge clk10hz) begin
    if (pb) begin
        count <= count + 1;
        if (count == 20) begin
            isKP <= 1;
        end
    end else begin
        count <= 0;
        isKP <= 0;
    end
end

endmodule

