module top_module(
    input clk,
    input reset,
    input direction,
    input [15:0] data_in,
    output [15:0] data_out,
    output msb_out,
    output lsb_out
);reg [15:0] shift_reg;
reg msb_shifted_out;
reg lsb_shifted_out;

always @(posedge clk or negedge clk) begin
    if (reset) begin
        shift_reg <= 16'b0;
        msb_shifted_out <= 1'b0;
        lsb_shifted_out <= 1'b0;
    end else begin
        if (direction) begin // shift right
            if (lsb_shifted_out) begin
                msb_shifted_out <= 1'b1;
                lsb_shifted_out <= 1'b0;
                shift_reg <= {1'b0, shift_reg[15:1]};
            end else begin
                shift_reg <= {data_in[15], shift_reg[15:1]};
            end
        end else begin // shift left
            if (msb_shifted_out) begin
                msb_shifted_out <= 1'b0;
                lsb_shifted_out <= 1'b1;
                shift_reg <= {shift_reg[14:0], 1'b0};
            end else begin
                shift_reg <= {shift_reg[14:0], data_in[0]};
            end
        end
    end
end

assign data_out = shift_reg;
assign msb_out = msb_shifted_out;
assign lsb_out = lsb_shifted_out;

endmodule

module top_module (
