module top_module(
  input [n-1:0] in,
  input signed_or_unsigned,
  output reg [n-1:0] min_val,
  output reg [n-1:0] max_val
);parameter n = 4; // number of input signals

reg [n-1:0] signed_in [2:0]; // 3-dimensional array to store signed inputs
reg [n-1:0] unsigned_in [2:0];

integer i;

// separate signed and unsigned inputs
always @(*) begin
  for (i = 0; i < n; i = i + 1) begin
    if (signed_or_unsigned == 1) begin
      signed_in[0][i] = in[i];
      signed_in[1][i] = in[i];
      signed_in[2][i] = in[i];
    end
    else begin
      unsigned_in[0][i] = in[i];
      unsigned_in[1][i] = in[i];
      unsigned_in[2][i] = in[i];
    end
  end
end

// calculate min and max values for signed inputs
always @(*) begin
  if (signed_or_unsigned == 1) begin
    min_val = signed_in[0];
    max_val = signed_in[0];
    for (i = 1; i < 3; i = i + 1) begin
      if (signed_in[i] < min_val)
        min_val = signed_in[i];
      if (signed_in[i] > max_val)
        max_val = signed_in[i];
    end
  end
end

// calculate min and max values for unsigned inputs
always @(*) begin
  if (signed_or_unsigned == 0) begin
    min_val = unsigned_in[0];
    max_val = unsigned_in[0];
    for (i = 1; i < 3; i = i + 1) begin
      if (unsigned_in[i] < min_val)
        min_val = unsigned_in[i];
      if (unsigned_in[i] > max_val)
        max_val = unsigned_in[i];
    end
  end
end

endmodule

module top_module(
    input [7:0] data_in,
    input shift,
    input load,
    output [7:0] data_out
);reg [7:0] shift_reg [2:0];
reg [1:0] stage;

always @(*) begin
    case(stage)
        0: begin
            if(load) begin
                shift_reg[0] <= data_in;
            end
            stage <= 1;
        end
        1: begin
            shift_reg[1] <= shift_reg[0];
            stage <= 2;
        end
        2: begin
            shift_reg[2] <= shift_reg[1];
            stage <= 3;
        end
        3: begin
            if(shift) begin
                shift_reg[2] <= {shift_reg[1][6:0], 1'b0};
            end else begin
                shift_reg[2] <= {1'b0, shift_reg[1][7:1]};
            end
            stage <= 1;
        end
    endcase
end

assign data_out = shift_reg[2];

endmodule

