description:
Design a 4-to-2 priority encoder with a control input that modifies its behavior. The module takes a 4-bit input and produces a 2-bit output based on the highest set bit in the input, with the output determined by the current control signal. Depending on the value of `ctrl`, the encoder selectively considers different bits of the input, effectively prioritizing which input bit should be reflected in the output. The outputs correspond to the positions of the highest active input, allowing for a flexible encoding scheme based on the control settings.
module top_module(
  input [3:0] in,
  input [1:0] ctrl,
  output reg [1:0] out
);

code:
module top_module(
  input [3:0] in,
  input [1:0] ctrl,
  output reg [1:0] out
);always @ (in or ctrl) begin
    if (ctrl == 2'b00) begin
      case (in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b01;
        4'b0100: out = 2'b10;
        4'b1000: out = 2'b11;
        default: out = 2'b00;
      endcase
    end else if (ctrl == 2'b01) begin
      case (in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b00;
        4'b0100: out = 2'b01;
        4'b1000: out = 2'b10;
        default: out = 2'b00;
      endcase
    end else if (ctrl == 2'b10) begin
      case (in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b00;
        4'b0100: out = 2'b00;
        4'b1000: out = 2'b01;
        default: out = 2'b00;
      endcase
    end else begin // ctrl == 2'b11
      case (in)
        4'b0001: out = 2'b00;
        4'b0010: out = 2'b00;
        4'b0100: out = 2'b00;
        4'b1000: out = 2'b00;
        default: out = 2'b00;
      endcase
    end
  end

endmodule

