module top_module(
    input clk,
    input rst,
    output reg red,
    output reg yellow,
    output reg green
);parameter GREEN_TIME = 10_000_000; // 10 seconds
parameter YELLOW_TIME = 2_000_000; // 2 seconds
parameter RED_TIME = 8_000_000; // 8 seconds

reg [23:0] counter;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        red <= 0;
        yellow <= 0;
        green <= 1;
    end else begin
        counter <= counter + 1;
        if (green && counter >= GREEN_TIME) begin
            green <= 0;
            yellow <= 1;
            counter <= 0;
        end else if (yellow && counter >= YELLOW_TIME) begin
            yellow <= 0;
            red <= 1;
            counter <= 0;
        end else if (red && counter >= RED_TIME) begin
            red <= 0;
            green <= 1;
            counter <= 0;
        end
    end
end

endmodule

